async function run({ inputFiles, outputDir, params }) {
  const text = String(params.sourceText || '');
  const mode = String(params.mode || 'all');
  const exportFile = params.exportJson === 'yes';

  Toolbox.log('【QuickJS 引擎】开始执行动态脚本任务...');
  Toolbox.log('>>> 当前运行平台:', Toolbox.platform);
  Toolbox.log('>>> 待处理文本长度:', text.length, '字符');
  Toolbox.setProgress(0.2, '正在分析输入数据...');

  let result = {
    timestamp: new Date().toISOString(),
    platform: Toolbox.platform,
    inputLength: text.length
  };

  if (mode === 'b64_enc') {
    Toolbox.setProgress(0.6, '正在执行 Base64 编码...');
    result.base64 = Toolbox.crypto.base64Encode(text);
    Toolbox.log('>>> Base64 编码结果:', result.base64);
  } else if (mode === 'b64_dec') {
    Toolbox.setProgress(0.6, '正在执行 Base64 解码...');
    try {
      result.decoded = Toolbox.crypto.base64Decode(text);
      Toolbox.log('>>> Base64 解码结果:', result.decoded);
    } catch (e) {
      Toolbox.error('Base64 解码失败:', String(e));
      return { success: false, message: 'Base64 解码失败，请输入合法的 Base64 字符串' };
    }
  } else {
    Toolbox.setProgress(0.4, '正在计算安全散列摘要 (MD5 & SHA256)...');
    const md5Val = Toolbox.crypto.md5(text);
    const shaVal = Toolbox.crypto.sha256(text);
    result.md5 = md5Val;
    result.sha256 = shaVal;
    Toolbox.log('>>> MD5 校验和:', md5Val);
    Toolbox.log('>>> SHA-256 散列:', shaVal);

    if (mode === 'all') {
      Toolbox.setProgress(0.7, '正在统计文本结构与字数...');
      result.base64 = Toolbox.crypto.base64Encode(text);
      result.lines = text.split(/\r?\n/).length;
      result.words = (text.match(/\b\w+\b/g) || []).length;
      Toolbox.log('>>> 总行数:', result.lines, '| 单词词数:', result.words);
    }
  }

  if (exportFile) {
    Toolbox.setProgress(0.9, '正在生成并落盘输出文件...');
    const outPath = outputDir + '/codec_report.json';
    Toolbox.fs.writeFile(outPath, JSON.stringify(result, null, 2));
    Toolbox.log('>>> 报告文件已持久化落盘至:', outPath);
  }

  Toolbox.setProgress(1.0, '计算完成！');
  return {
    success: true,
    message: 'QuickJS 脚本执行成功！已完成数据运算与格式化',
    data: result
  };
}
